create table website_diagnosis_snapshots(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='website-diagnosis.v1'),input_sha256 char(64) not null,status text not null check(status='complete_with_gaps'),fact_level text not null check(fact_level='F2'),target_count integer not null check(target_count between 1 and 5),succeeded_count integer not null check(succeeded_count>=0),blocked_count integer not null check(blocked_count>=0),failed_count integer not null check(failed_count>=0),pages jsonb not null check(jsonb_typeof(pages)='array'),strengths jsonb not null check(jsonb_typeof(strengths)='array'),gaps jsonb not null check(jsonb_typeof(gaps)='array'),self_reported_claims jsonb not null check(jsonb_typeof(self_reported_claims)='array'),decision_signals jsonb not null check(jsonb_typeof(decision_signals)='array'),publication_authorized boolean not null check(publication_authorized=false),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256));
create trigger website_diagnosis_snapshots_append_only before update or delete on website_diagnosis_snapshots for each row execute function reject_immutable_mutation();create trigger website_diagnosis_snapshots_no_truncate before truncate on website_diagnosis_snapshots for each statement execute function reject_immutable_mutation();alter table website_diagnosis_snapshots enable row level security;alter table website_diagnosis_snapshots force row level security;create policy website_diagnosis_snapshots_tenant_isolation on website_diagnosis_snapshots using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
